"use client"

import { useEffect, useState, useRef } from "react"
import { useRouter } from "next/navigation"
import { ArrowLeft, Mic, MicOff, PhoneOff } from "lucide-react"
import { Button } from "@/components/ui/button"
import { personas } from "@/lib/personas"
import type { ChatStatus, Message, InterviewData } from "@/lib/types"
import { VoiceOrb } from "@/components/voice-orb"
import { ChatTranscript } from "@/components/chat-transcript"
import { StatusBadge } from "@/components/status-badge"

export default function InterviewPage() {
  const router = useRouter()
  const [interviewData, setInterviewData] = useState<InterviewData | null>(null)
  const [status, setStatus] = useState<ChatStatus>("idle")
  const [messages, setMessages] = useState<Message[]>([])
  const [micActive, setMicActive] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const pcRef = useRef<RTCPeerConnection | null>(null)
  const dcRef = useRef<RTCDataChannel | null>(null)
  const audioElRef = useRef<HTMLAudioElement | null>(null)

  // Load User Data
  useEffect(() => {
    const stored = sessionStorage.getItem("interviewData")
    if (stored) {
      setInterviewData(JSON.parse(stored))
    } else {
      router.push("/")
    }

    // Mount hidden audio element
    const audioEl = document.createElement("audio")
    audioEl.autoplay = true
    audioElRef.current = audioEl
    document.body.appendChild(audioEl)

    return () => {
      cleanup()
      audioEl.remove()
    }
  }, [router])

  // Start Session Effect
  useEffect(() => {
    if (interviewData && !pcRef.current) {
      startRealtimeSession()
    }
  }, [interviewData])

  const cleanup = () => {
    if (pcRef.current) pcRef.current.close()
    pcRef.current = null
  }

  const startRealtimeSession = async () => {
    try {
      setStatus("processing")
      console.log("Starting Realtime Session...")

      // 1. Get Ephemeral Token
      const tokenRes = await fetch(`/api/session?personaId=${interviewData?.personaId}`)
      const data = await tokenRes.json()
      const EPHEMERAL_KEY = data.client_secret.value

      // 2. Setup Peer Connection
      const pc = new RTCPeerConnection()
      pcRef.current = pc

      // Handle Audio Output
      pc.ontrack = (e) => {
        console.log("Audio track received")
        if (audioElRef.current) {
          audioElRef.current.srcObject = e.streams[0]
        }
      }

      // Handle Microphone Input
      const ms = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true
        }
      })
      pc.addTrack(ms.getAudioTracks()[0])
      setMicActive(true)

      // 3. Setup Data Channel for Events
      const dc = pc.createDataChannel("oai-events")
      dcRef.current = dc

      dc.onopen = () => {
        console.log("Data Channel Open")
        setStatus("idle") // Ready

        // Send initial "response.create" to trigger greeting? 
        // Actually, usually we wait for user, but we can trigger a greeting.
        const greeting = {
          type: "response.create",
          response: {
            modalities: ["text", "audio"],
            instructions: "Please say hello to the user and introduce yourself as Weya."
          }
        }
        dc.send(JSON.stringify(greeting))
      }

      dc.onmessage = (e) => {
        const event = JSON.parse(e.data)

        // Log for debugging
        if (event.type === 'response.audio_transcript.delta') {
          // We could show live captions here
        }

        if (event.type === 'response.audio.done') {
          setStatus("idle")
        }

        if (event.type === 'input_audio_buffer.speech_started') {
          console.log("User started speaking")
          setStatus("listening")
          // Interrupt? The server usually handles interruption if configured, 
          // but we might want to manually clear the current response visualization.
        }

        if (event.type === 'response.output_item.added') {
          // Track items
        }

        // Capture final transcripts for chat history
        if (event.type === 'conversation.item.created') {
          const item = event.item
          if (item.type === 'message' && item.role === 'user') {
            // Log User Message
            const text = item.content[0]?.text || "(Audio)"
            addMessage("user", text)
          }
          if (item.type === 'message' && item.role === 'assistant') {
            // Start of assistant message
            setStatus("speaking")
          }
        }
        // Capture assistant final text
        if (event.type === 'response.text.done') {
          addMessage("assistant", event.text)
        }
        // Actually, 'response.audio_transcript.done' gives the transcript of what was said
        if (event.type === 'response.audio_transcript.done') {
          addMessage("assistant", event.transcript)
        }
      }

      // 4. SDP Handshake
      const offer = await pc.createOffer()
      await pc.setLocalDescription(offer)

      const baseUrl = "https://api.openai.com/v1/realtime"
      const model = "gpt-4o-realtime-preview-2024-10-01"
      const sdpRes = await fetch(`${baseUrl}?model=${model}`, {
        method: "POST",
        body: offer.sdp,
        headers: {
          Authorization: `Bearer ${EPHEMERAL_KEY}`,
          "Content-Type": "application/sdp"
        },
      })

      const answer = {
        type: "answer",
        sdp: await sdpRes.text(),
      }
      await pc.setRemoteDescription(answer as RTCSessionDescriptionInit)

    } catch (err: any) {
      console.error("Realtime connection failed:", err)
      setError("Failed to connect: " + err.message)
      setStatus("error")
    }
  }

  const addMessage = (role: "user" | "assistant", content: string) => {
    setMessages(prev => {
      // Avoid dups if possible, or valid unique IDs
      return [...prev, {
        id: Date.now().toString(),
        role,
        content,
        timestamp: new Date()
      }]
    })

    // OPTIONAL: Log to Supabase here 
  }

  return (
    <div className="flex h-screen flex-col bg-gradient-to-br from-[#E8E5F5] via-[#F3E8F0] to-[#F5E8EB]">
      {/* Header */}
      <header className="flex items-center justify-between border-b border-white/40 bg-white/30 px-6 py-4 backdrop-blur-md">
        <div className="flex items-center gap-4">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => router.push("/")}
            className="rounded-full hover:bg-white/50"
          >
            <ArrowLeft className="h-5 w-5 text-gray-700" />
          </Button>
          <div>
            <h1 className="text-lg font-semibold text-gray-900">{interviewData?.personaId}</h1>
          </div>
        </div>
        <StatusBadge status={status} />
      </header>

      {/* Main Content */}
      <main className="relative flex flex-1 flex-col overflow-hidden">
        {/* Chat Transcript Layer */}
        <div className="absolute inset-0 z-0 pb-32">
          <ChatTranscript messages={messages} />
        </div>

        {/* Voice Orb Layer (Centered/Bottom) */}
        <div className="pointer-events-none absolute bottom-0 left-0 right-0 z-10 flex flex-col items-center justify-end bg-gradient-to-t from-[#F5E8EB] via-[#F5E8EB]/80 to-transparent pb-12 pt-24">
          <div className="mb-8">
            <VoiceOrb status={status} />
          </div>

          <div className="pointer-events-auto flex items-center gap-4">
            <Button
              variant={micActive ? "default" : "secondary"}
              size="lg"
              className="h-14 w-14 rounded-full shadow-lg"
              onClick={() => {
                // Toggle Mute logic
                if (pcRef.current) {
                  pcRef.current.getSenders().forEach(sender => {
                    if (sender.track) sender.track.enabled = !micActive
                  })
                  setMicActive(!micActive)
                }
              }}
            >
              {micActive ? <Mic className="h-6 w-6" /> : <MicOff className="h-6 w-6" />}
            </Button>

            <Button
              variant="destructive"
              size="lg"
              className="h-14 w-14 rounded-full shadow-lg"
              onClick={() => {
                cleanup()
                router.push("/")
              }}
            >
              <PhoneOff className="h-6 w-6" />
            </Button>
          </div>
          {error && <div className="mt-4 text-red-500 bg-white/80 px-4 py-2 rounded">{error}</div>}
        </div>
      </main>
    </div>
  )
}
