"use client"

import { motion } from "framer-motion"
import type { ChatStatus } from "@/lib/types"
import { Loader2 } from "lucide-react"

interface VoiceOrbProps {
  status: ChatStatus
}

export function VoiceOrb({ status }: VoiceOrbProps) {
  return (
    <div className="relative flex items-center justify-center">
      {/* Main Orb */}
      <motion.div
        className="relative z-10 h-40 w-40 rounded-full bg-gradient-to-br from-purple-400 via-blue-400 to-pink-400 shadow-2xl shadow-purple-500/40"
        animate={
          status === "idle"
            ? {
                scale: [1, 1.02, 1],
                opacity: [0.7, 0.85, 0.7],
              }
            : status === "listening"
              ? {
                  scale: [1, 1.08, 1],
                  opacity: [0.9, 1, 0.9],
                }
              : status === "speaking"
                ? {
                    scale: [1, 1.12, 1],
                    opacity: [1, 0.95, 1],
                  }
                : {
                    scale: 1,
                    opacity: 0.5,
                  }
        }
        transition={
          status === "idle"
            ? {
                duration: 4,
                repeat: Number.POSITIVE_INFINITY,
                ease: "easeInOut",
              }
            : status === "listening"
              ? {
                  duration: 2,
                  repeat: Number.POSITIVE_INFINITY,
                  ease: "easeInOut",
                }
              : status === "speaking"
                ? {
                    duration: 0.6,
                    repeat: Number.POSITIVE_INFINITY,
                    ease: "easeInOut",
                  }
                : {}
        }
      >
        {status === "processing" && (
          <div className="absolute inset-0 flex items-center justify-center">
            <Loader2 className="h-10 w-10 animate-spin text-white" />
          </div>
        )}
      </motion.div>

      {/* Outer Ring - Listening/Speaking */}
      {(status === "listening" || status === "speaking") && (
        <motion.div
          className="absolute rounded-full border-2 border-purple-300"
          initial={{ scale: 1, opacity: 0.7 }}
          animate={{
            scale: [1, 1.4, 1],
            opacity: [0.7, 0, 0.7],
          }}
          transition={{
            duration: status === "listening" ? 2 : 1.2,
            repeat: Number.POSITIVE_INFINITY,
            ease: "easeOut",
          }}
          style={{
            width: "10rem",
            height: "10rem",
          }}
        />
      )}

      {/* Second Ring - Listening */}
      {status === "listening" && (
        <motion.div
          className="absolute rounded-full border border-blue-300"
          initial={{ scale: 1, opacity: 0.5 }}
          animate={{
            scale: [1, 1.6, 1],
            opacity: [0.5, 0, 0.5],
          }}
          transition={{
            duration: 2.5,
            repeat: Number.POSITIVE_INFINITY,
            ease: "easeOut",
            delay: 0.4,
          }}
          style={{
            width: "10rem",
            height: "10rem",
          }}
        />
      )}
    </div>
  )
}
